//! Replays traces of the SDK TLA+ model into the core (docs/spec.md §11.1).
//!
//! Each trace is a behaviour of `tla/sdk/SDK.tla`, generated by `cargo xtask
//! tla-traces` (narrowed by `tests/tla/Replay.tla` to the schedules this SDK
//! implements). Every modelled step becomes the core input it stands for: an
//! application call, a callback settling, a transport opening or failing, a
//! timer, or a frame item, translated from the model's abstract frame to a
//! concrete reply. After each step the core must agree with the model:
//!
//! - its client and subscription states;
//! - its events: one per state change of the client, of each subscription and
//!   of each server-side subscription, and a publication exactly when the
//!   model hands one to the application, with that offset and the payload of
//!   that offset (so a wrong delta base shows);
//! - its commands (kind, channel, recovery position, token) and callbacks;
//! - its timers: reconnect and resubscribe are armed exactly when the model
//!   waits for them.
//!
//! Model steps the core takes inside the step before (a subscribe flow
//! starting) produce no input; their outputs are matched against what the
//! core already produced.

use crate::time::Instant;
use std::collections::HashMap;

use serde_json::Value;

use super::{
    Callback, CallbackError, CloseReason, Core, CoreConfig, Event, Input, Op, OpenRequest, State,
    SubConfig, SubKey, SubState, TimerKey, TransportId, TransportKind,
};
use crate::proto;
use crate::types::StreamPosition;

const NONE: i64 = -1;
const SENTINEL: i64 = 0;

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v.get(k).and_then(Value::as_str).unwrap_or_default()
}
fn i(v: &Value, k: &str) -> i64 {
    v.get(k).and_then(Value::as_i64).unwrap_or_default()
}
fn b(v: &Value, k: &str) -> bool {
    v.get(k).and_then(Value::as_bool).unwrap_or_default()
}
fn arr<'a>(v: &'a Value, k: &str) -> &'a [Value] {
    v.get(k)
        .and_then(Value::as_array)
        .map_or(&[], Vec::as_slice)
}
fn u(v: &Value, k: &str) -> u64 {
    u64::try_from(i(v, k)).unwrap_or(0)
}

fn epoch(ep: i64) -> String {
    match ep {
        NONE => String::new(),
        SENTINEL => super::sub::INVALIDATED_EPOCH.to_owned(),
        n => format!("e{n}"),
    }
}

/// The payload of the publication at `offset`: each one extends the previous,
/// so a delta from any earlier publication exists.
fn payload(offset: u64) -> Vec<u8> {
    let mut v = b"p".to_vec();
    for o in 1..=offset {
        v.extend_from_slice(format!("|{o}").as_bytes());
    }
    v
}

const B64: &[u8; 64] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ_abcdefghijklmnopqrstuvwxyz~";

fn fossil_int(mut n: u32, out: &mut Vec<u8>) {
    if n == 0 {
        out.push(b'0');
        return;
    }
    let mut d = Vec::new();
    while n > 0 {
        d.push(B64[(n & 63) as usize]);
        n >>= 6;
    }
    d.reverse();
    out.extend(d);
}

/// A fossil delta from `payload(base)` to `payload(offset)`: copy the base,
/// insert the rest. Applied to any other base it gives other data (or a
/// checksum error).
fn delta(base: u64, offset: u64) -> Vec<u8> {
    let (from, to) = (payload(base), payload(offset));
    let n = |x: usize| u32::try_from(x).unwrap_or(u32::MAX);
    let mut d = Vec::new();
    fossil_int(n(to.len()), &mut d);
    d.push(b'\n');
    fossil_int(n(from.len()), &mut d);
    d.extend_from_slice(b"@0,");
    let rest = &to[from.len()..];
    fossil_int(n(rest.len()), &mut d);
    d.push(b':');
    d.extend_from_slice(rest);
    fossil_int(crate::delta::checksum(&to), &mut d);
    d.push(b';');
    d
}

fn publication(offset: u64, base: Option<u64>) -> proto::Publication {
    match base {
        Some(b) if b > 0 => proto::Publication {
            offset,
            data: delta(b, offset).into(),
            delta: true,
            ..Default::default()
        },
        _ => proto::Publication {
            offset,
            data: payload(offset).into(),
            ..Default::default()
        },
    }
}

#[derive(Debug, Clone)]
struct Consts {
    chans: Vec<String>,
    server_chans: Vec<String>,
    ordered: bool,
    recoverable: bool,
    get_state: bool,
    delta: bool,
    conn_token: bool,
    sub_token: bool,
    refresh: bool,
}

impl Consts {
    fn from(c: &Value) -> Self {
        let names = |k: &str| {
            arr(c, k)
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_owned)
                .collect()
        };
        Self {
            chans: names("Chans"),
            server_chans: names("ServerChans"),
            ordered: b(c, "Ordered"),
            recoverable: b(c, "Recoverable"),
            get_state: b(c, "GetState"),
            delta: b(c, "Delta"),
            conn_token: b(c, "ConnToken"),
            sub_token: b(c, "SubToken"),
            refresh: b(c, "Refresh"),
        }
    }
}

/// What a step must have produced, matched against the core's outputs.
#[derive(Default, Debug)]
struct Produced {
    events: Vec<Event>,
    commands: Vec<proto::Command>,
    callbacks: Vec<Callback>,
}

struct Replay {
    consts: Consts,
    core: Core,
    now: Instant,
    keys: HashMap<String, SubKey>,
    /// Every key ever used, removed ones too.
    names: HashMap<SubKey, String>,
    next_key: SubKey,
    transport: Option<TransportId>,
    /// The connect command of an emulation open, sent with the stream request.
    initial: Option<proto::Command>,
    ids: HashMap<i64, u32>,
    /// Model callback (its record) → core flow.
    flows: HashMap<String, u64>,
    out: Produced,
    /// The model's state, step by step.
    state: serde_json::Map<String, Value>,
    log: Vec<String>,
}

type R = Result<(), String>;

impl Replay {
    fn new(consts: Consts, init: &serde_json::Map<String, Value>) -> Self {
        let cfg = CoreConfig {
            protocol: crate::codec::Protocol::Protobuf,
            transports: vec![if consts.ordered {
                TransportKind::WebSocket
            } else {
                TransportKind::HttpStream
            }],
            has_get_token: consts.conn_token,
            seed: 7,
            ..CoreConfig::default()
        };
        let mut r = Self {
            consts,
            core: Core::new(cfg),
            now: Instant::now(),
            keys: HashMap::new(),
            names: HashMap::new(),
            next_key: 1,
            transport: None,
            initial: None,
            ids: HashMap::new(),
            flows: HashMap::new(),
            out: Produced::default(),
            state: init.clone(),
            log: Vec::new(),
        };
        for c in r.consts.chans.clone() {
            r.new_sub(&c);
        }
        r
    }

    fn sub_config(&self, c: &str) -> SubConfig {
        let mut cfg = SubConfig::new(c);
        cfg.recoverable = self.consts.recoverable;
        cfg.positioned = self.consts.recoverable;
        cfg.has_get_token = self.consts.sub_token;
        cfg.has_get_state = self.consts.get_state;
        cfg.delta = self.consts.delta;
        cfg
    }

    fn new_sub(&mut self, c: &str) {
        let key = self.next_key;
        self.next_key += 1;
        self.keys.insert(c.to_owned(), key);
        self.names.insert(key, c.to_owned());
        let config = Box::new(self.sub_config(c));
        self.input(Input::App(Op::NewSubscription { key, config }));
    }

    /// Feeds an input, acking deliveries, and collects what it produced.
    fn input(&mut self, input: Input) {
        let mut out = self.core.step(input, self.now);
        loop {
            if let Some(o) = out.open.take() {
                self.open(o);
            }
            self.out.commands.extend(
                out.commands
                    .drain(..)
                    .map(|(_, c)| c)
                    .filter(|c| *c != proto::Command::default()),
            );
            self.out.callbacks.append(&mut out.callbacks);
            if out.events.is_empty() {
                break;
            }
            self.out.events.append(&mut out.events);
            out = self.core.step(
                Input::Delivered {
                    ok: true,
                    panic: None,
                },
                self.now,
            );
        }
    }

    fn open(&mut self, o: OpenRequest) {
        self.transport = Some(o.transport);
        self.initial = o.initial;
    }

    fn fire(&mut self, key: TimerKey) -> R {
        let at = self
            .core
            .timers
            .deadline(key)
            .ok_or_else(|| format!("timer {key:?} isn't armed"))?;
        self.now = self.now.max(at);
        self.input(Input::TimerFired {
            key,
            late: false,
            last_received: None,
        });
        Ok(())
    }

    fn key(&self, c: &str) -> SubKey {
        self.keys.get(c).copied().unwrap_or_default()
    }

    fn cur(&self) -> Result<TransportId, String> {
        self.transport.ok_or_else(|| "no transport".to_owned())
    }

    fn id(&self, model: i64) -> Result<u32, String> {
        self.ids
            .get(&model)
            .copied()
            .ok_or_else(|| format!("no core command for model command {model}"))
    }

    fn settle(&mut self, cb: &Value, result: Result<Option<String>, CallbackError>) -> R {
        let flow = self
            .flows
            .remove(&cb.to_string())
            .ok_or_else(|| format!("no core callback for {cb}"))?;
        self.input(Input::TokenSettled { flow, result });
        Ok(())
    }

    // ---- frames ----

    fn sub_result(&self, r: &Value) -> proto::SubscribeResult {
        let (lo, hi) = (u(r, "lo"), u(r, "hi"));
        let delta = b(r, "delta");
        let publications = (lo..=hi)
            .map(|o| publication(o, (delta && o > lo).then(|| o - 1)))
            .collect();
        proto::SubscribeResult {
            recoverable: b(r, "rec"),
            positioned: b(r, "rec"),
            epoch: if b(r, "rec") {
                epoch(i(r, "ep"))
            } else {
                String::new()
            },
            offset: if b(r, "rec") { u(r, "off") } else { 0 },
            recovered: b(r, "rcv"),
            was_recovering: b(r, "was"),
            publications,
            delta,
            ..Default::default()
        }
    }

    fn error(code: &str) -> proto::Error {
        let (code, temporary) = match code {
            "temp" => (100, true),
            "expired" => (crate::codes::TOKEN_EXPIRED, false),
            "unrec" => (crate::codes::UNRECOVERABLE_POSITION, false),
            "already" => (105, false),
            _ => (103, false),
        };
        proto::Error {
            code,
            message: "model".into(),
            temporary,
        }
    }

    /// The model's frame as a concrete reply or push.
    fn frame(&self, f: &Value) -> Result<proto::Reply, String> {
        let mut r = proto::Reply::default();
        let id = i(f, "id");
        if id > 0 {
            r.id = self.id(id)?;
        }
        let ok = b(f, "ok");
        let ch = s(f, "ch").to_owned();
        match s(f, "k") {
            "conrep" if ok => {
                let subs = f
                    .get("srs")
                    .and_then(Value::as_object)
                    .map(|m| {
                        m.iter()
                            .map(|(c, res)| (c.clone(), self.sub_result(res)))
                            .collect()
                    })
                    .unwrap_or_default();
                r.connect = Some(proto::ConnectResult {
                    client: "c".into(),
                    subs,
                    expires: self.consts.refresh,
                    ttl: if self.consts.refresh { 3600 } else { 0 },
                    ..Default::default()
                });
            }
            "subrep" if ok => r.subscribe = Some(self.sub_result(&f["res"])),
            "unsubrep" if ok => r.unsubscribe = Some(proto::UnsubscribeResult {}),
            "refrep" if ok => {
                r.refresh = Some(proto::RefreshResult {
                    expires: true,
                    ttl: 3600,
                    ..Default::default()
                });
            }
            "srefrep" if ok => {
                r.sub_refresh = Some(proto::SubRefreshResult {
                    expires: true,
                    ttl: 3600,
                    ..Default::default()
                });
            }
            "conrep" | "subrep" | "unsubrep" | "refrep" | "srefrep" => {
                r.error = Some(Self::error(s(f, "code")));
            }
            "pub" => {
                let base = (b(f, "delta") && i(f, "base") > 0).then(|| u(f, "base"));
                r.push = Some(proto::Push {
                    channel: ch,
                    r#pub: Some(publication(u(f, "off"), base)),
                    ..Default::default()
                });
            }
            "unsubpush" => {
                let code = match s(f, "code") {
                    "terminal" => 2000,
                    "resub" => 2500,
                    _ => crate::codes::UNSUBSCRIBE_STATE_INVALIDATED,
                };
                r.push = Some(proto::Push {
                    channel: ch,
                    unsubscribe: Some(proto::Unsubscribe {
                        code,
                        reason: "model".into(),
                    }),
                    ..Default::default()
                });
            }
            "disc" => {
                let code = match s(f, "code") {
                    "reconnect" => 3001,
                    "terminal" => 3500,
                    _ => crate::codes::DISCONNECT_STATE_INVALIDATED,
                };
                r.push = Some(proto::Push {
                    disconnect: Some(proto::Disconnect {
                        code,
                        reason: "model".into(),
                        reconnect: false,
                    }),
                    ..Default::default()
                });
            }
            k => return Err(format!("frame kind {k}")),
        }
        Ok(r)
    }

    // ---- one model step ----

    fn step(&mut self, diff: &serde_json::Map<String, Value>) -> R {
        let prev = Value::Object(self.state.clone());
        for (k, v) in diff {
            self.state.insert(k.clone(), v.clone());
        }
        let next = Value::Object(self.state.clone());
        let act = s(&next, "act").to_owned();
        self.log.push(act.clone());
        if !arr(&next, "err").is_empty() {
            return Err(format!("the model flags {:?}", next["err"]));
        }
        // What the core produced ahead of the model must be taken by the model's
        // own steps for it (a subscribe flow starting) before anything else.
        if act != "Sdk_StartFlow" {
            self.no_leftovers()?;
        }
        self.apply(&act, &prev, &next)?;
        self.check(&act, &prev, &next)
    }

    fn no_leftovers(&self) -> R {
        if !self.out.commands.is_empty() {
            return Err(format!(
                "core sent commands the model doesn't: {:?}",
                self.out.commands
            ));
        }
        if !self.out.callbacks.is_empty() {
            return Err(format!(
                "core started callbacks the model doesn't: {:?}",
                self.out.callbacks
            ));
        }
        Ok(())
    }

    fn changed_sub(prev: &Value, next: &Value, from: &[&str], to: &str) -> Option<String> {
        let (ps, ns) = (prev.get("sub")?.as_object()?, next.get("sub")?.as_object()?);
        ns.iter()
            .find(|(c, n)| s(n, "st") == to && from.contains(&s(&ps[c.as_str()], "st")))
            .map(|(c, _)| c.clone())
    }

    fn removed_cb(prev: &Value, next: &Value) -> Option<Value> {
        let n = arr(next, "cbs");
        arr(prev, "cbs").iter().find(|x| !n.contains(x)).cloned()
    }

    #[allow(clippy::too_many_lines)]
    fn apply(&mut self, act: &str, prev: &Value, next: &Value) -> R {
        match act {
            "App_Connect" => self.input(Input::App(Op::Connect)),
            "App_Disconnect" => self.input(Input::App(Op::Disconnect)),
            "App_Close" => self.input(Input::App(Op::Close)),
            "App_Subscribe" => {
                let c = Self::changed_sub(prev, next, &["unsubscribed"], "subscribing")
                    .ok_or("which subscribe?")?;
                self.input(Input::App(Op::Subscribe(self.key(&c))));
            }
            "App_Unsubscribe" => {
                let c =
                    Self::changed_sub(prev, next, &["subscribing", "subscribed"], "unsubscribed")
                        .ok_or("which unsubscribe?")?;
                self.input(Input::App(Op::Unsubscribe(self.key(&c))));
            }
            "App_Replace" => {
                let c = self
                    .consts
                    .chans
                    .iter()
                    .find(|c| {
                        i(&prev["sub"][c.as_str()], "obj") != i(&next["sub"][c.as_str()], "obj")
                    })
                    .cloned()
                    .ok_or("which replace?")?;
                let old = self.key(&c);
                self.input(Input::App(Op::RemoveSubscription(old)));
                self.new_sub(&c);
            }
            "App_Call" | "Env_CallTimeout" | "Env_TokenExpires" | "Sdk_StartFlow" => {}
            a if a.starts_with("Srv_") => {}
            "Sdk_ReconnectTimer" => {
                if self.core.timers.is_armed(TimerKey::Reconnect) {
                    self.fire(TimerKey::Reconnect)?;
                }
            }
            "Sdk_ResubscribeTimer" => {
                let c = self
                    .consts
                    .chans
                    .iter()
                    .find(|c| {
                        b(&prev["sub"][c.as_str()], "tmr") && !b(&next["sub"][c.as_str()], "tmr")
                    })
                    .cloned()
                    .ok_or("which resubscribe timer?")?;
                self.fire(TimerKey::Resubscribe(self.key(&c)))?;
            }
            "Sdk_RefreshTimer" => self.fire(TimerKey::Refresh)?,
            "Sdk_SubRefreshTimer" => {
                let c = self
                    .consts
                    .chans
                    .iter()
                    .find(|c| {
                        s(&prev["sub"][c.as_str()], "rph") == "timer"
                            && s(&next["sub"][c.as_str()], "rph") == "token"
                    })
                    .cloned()
                    .ok_or("which sub refresh timer?")?;
                self.fire(TimerKey::SubRefresh(self.key(&c)))?;
            }
            "Env_Open" => {
                let t = self.cur()?;
                self.input(Input::Opened { transport: t });
                if let Some(c) = self.initial.take() {
                    self.out.commands.insert(0, c);
                }
            }
            "Env_Drop" => {
                let t = self.cur()?;
                let reason = if s(&prev["cl"], "ph") == "open" {
                    CloseReason::Failed {
                        status: None,
                        message: "model".into(),
                        source: None,
                    }
                } else {
                    CloseReason::Eof
                };
                self.input(Input::Closed {
                    transport: t,
                    reason,
                });
            }
            "Env_Timeout" => {
                let p = arr(prev, "pend").iter().find(|p| {
                    !arr(next, "pend").contains(p) || s(&next["cl"], "tid") != s(&prev["cl"], "tid")
                });
                // A teardown clears every pending command: find the one whose
                // timer the model fired by elimination.
                let p = p.ok_or("which timeout?")?.clone();
                let key = if s(&p, "k") == "connect" {
                    TimerKey::ConnectReply
                } else {
                    TimerKey::Command(self.id(i(&p, "id"))?)
                };
                self.fire(key)?;
            }
            "Env_WriteError" => {
                let gone: Vec<&Value> = arr(prev, "toS")
                    .iter()
                    .filter(|c| !arr(next, "toS").contains(c))
                    .collect();
                let cmd = gone.first().ok_or("which write error?")?;
                let t = self.cur()?;
                let id = self.id(i(cmd, "id"))?;
                self.input(Input::WriteFailed {
                    transport: t,
                    command_ids: vec![id],
                    had_pong: false,
                });
            }
            "Cb_ConnToken" | "Cb_ConnRefresh" => {
                let x = Self::removed_cb(prev, next).ok_or("which callback?")?;
                let (pc, nc) = (&prev["cl"], &next["cl"]);
                let stale = if act == "Cb_ConnToken" {
                    i(&x, "att") != i(pc, "att") || s(pc, "ph") != "token"
                } else {
                    i(&x, "att") != i(pc, "cid")
                        || s(pc, "st") != "connected"
                        || s(pc, "rph") != "token"
                };
                let result = if stale {
                    Ok(Some("stale".into()))
                } else if s(nc, "st") == "disconnected" {
                    Err(CallbackError::Unauthorized)
                } else if (act == "Cb_ConnToken" && s(nc, "ph") == "wait")
                    || (act == "Cb_ConnRefresh" && s(nc, "rph") == "timer")
                {
                    Err(CallbackError::Other(std::sync::Arc::new(
                        std::io::Error::other("model"),
                    )))
                } else {
                    Ok(Some(format!("t{}", i(nc, "tok"))))
                };
                self.settle(&x, result)?;
            }
            "Cb_SubToken" | "Cb_SubRefresh" => {
                let x = Self::removed_cb(prev, next).ok_or("which callback?")?;
                let c = s(&x, "ch");
                let (ps, ns) = (&prev["sub"][c], &next["sub"][c]);
                let stale = if act == "Cb_SubToken" {
                    s(ps, "st") != "subscribing" || i(&x, "att") != i(ps, "flow")
                } else {
                    i(&x, "att") != i(ps, "gen")
                        || s(ps, "st") != "subscribed"
                        || s(ps, "rph") != "token"
                };
                let result = if stale {
                    Ok(Some("stale".into()))
                } else if s(ns, "st") == "unsubscribed" {
                    Err(CallbackError::Unauthorized)
                } else if (act == "Cb_SubToken" && b(ns, "tmr") && !b(ps, "tmr"))
                    || (act == "Cb_SubRefresh" && s(ns, "rph") == "timer")
                {
                    Err(CallbackError::Other(std::sync::Arc::new(
                        std::io::Error::other("model"),
                    )))
                } else {
                    Ok(Some(format!("s{}", i(ns, "tok"))))
                };
                self.settle(&x, result)?;
            }
            "Cb_GetState" => {
                let x = Self::removed_cb(prev, next).ok_or("which callback?")?;
                let c = s(&x, "ch");
                let (ps, ns) = (&prev["sub"][c], &next["sub"][c]);
                let stale = s(ps, "st") != "subscribing" || i(&x, "att") != i(ps, "flow");
                let st = &prev["str"][c];
                let result = if !stale && b(ns, "tmr") && !b(ps, "tmr") {
                    Err(CallbackError::Other(std::sync::Arc::new(
                        std::io::Error::other("model"),
                    )))
                } else {
                    Ok(StreamPosition {
                        offset: u(st, "top"),
                        epoch: epoch(i(st, "ep")),
                    })
                };
                let flow = self
                    .flows
                    .remove(&x.to_string())
                    .ok_or_else(|| format!("no core callback for {x}"))?;
                self.input(Input::StateSettled { flow, result });
            }
            "Sdk_Deliver" | "Sdk_SSSubscribed" | "Sdk_SSDeliver" => {
                if !self.core.has_pending_delivery() {
                    return Err("the model delivers, the core has nothing queued".into());
                }
                self.input(Input::DeliverNext);
            }
            "Sdk_StaleReply"
            | "Sdk_ConnectReply"
            | "Sdk_SubscribeReply"
            | "Sdk_UnsubscribeReply"
            | "Sdk_Publication"
            | "Sdk_UnsubscribePush"
            | "Sdk_DisconnectPush"
            | "Sdk_RefreshReply"
            | "Sdk_SubRefreshReply" => {
                let f = arr(prev, "toC").first().ok_or("no frame")?.clone();
                let reply = self.frame(&f)?;
                let t = self.cur()?;
                self.input(Input::Item {
                    transport: t,
                    reply: Box::new(reply),
                });
            }
            a => return Err(format!("unsupported action {a}")),
        }
        Ok(())
    }

    // ---- what the step must have produced ----

    #[allow(clippy::too_many_lines)]
    fn check(&mut self, act: &str, prev: &Value, next: &Value) -> R {
        // Client state and its event.
        let (pst, nst) = (s(&prev["cl"], "st"), s(&next["cl"], "st"));
        let want = match nst {
            "disconnected" => State::Disconnected,
            "connecting" => State::Connecting,
            "connected" => State::Connected,
            _ => State::Closed,
        };
        if self.core.state() != want {
            return Err(format!(
                "client state: core {:?}, model {nst}",
                self.core.state()
            ));
        }
        // The events this step must have produced, in no particular order
        // within the step.
        let mut expect: Vec<String> = Vec::new();
        if pst != nst {
            match nst {
                "closed" if pst != "disconnected" => expect.push("disconnected".into()),
                "closed" => {}
                st => expect.push(st.to_owned()),
            }
        }
        // Client-side subscriptions (App_Replace: the removed object's event).
        for c in self.consts.chans.clone() {
            let (ps, ns) = (&prev["sub"][c.as_str()], &next["sub"][c.as_str()]);
            let replaced = i(ps, "obj") != i(ns, "obj");
            let (from, to) = (
                s(ps, "st"),
                if replaced {
                    "unsubscribed"
                } else {
                    s(ns, "st")
                },
            );
            if from != to {
                expect.push(format!("{to} {c}"));
            }
            if !replaced {
                let want = match s(ns, "st") {
                    "subscribed" => SubState::Subscribed,
                    "subscribing" => SubState::Subscribing,
                    _ => SubState::Unsubscribed,
                };
                let got = self.core.subscription(self.key(&c)).map(|x| x.0);
                if got != Some(want) {
                    return Err(format!(
                        "subscription {c}: core {got:?}, model {}",
                        s(ns, "st")
                    ));
                }
            }
        }
        for c in self.consts.server_chans.clone() {
            let (ps, ns) = (&prev["ss"][c.as_str()], &next["ss"][c.as_str()]);
            if s(ps, "st") != s(ns, "st") {
                expect.push(format!("server_{} {c}", s(ns, "st")));
            }
        }
        // Publications handed to the application.
        let delivered = match act {
            "Sdk_Publication" => {
                let f = &arr(prev, "toC")[0];
                let c = s(f, "ch");
                let to_sub = self.consts.chans.iter().any(|x| x == c)
                    && s(&prev["sub"][c], "st") == "subscribed";
                let to_ss = !to_sub
                    && self.consts.server_chans.iter().any(|x| x == c)
                    && s(&prev["ss"][c], "st") == "subscribed";
                (to_sub || to_ss).then(|| (c.to_owned(), u(f, "off")))
            }
            "Sdk_Deliver" | "Sdk_SSDeliver" => {
                let c = self
                    .consts
                    .chans
                    .iter()
                    .chain(&self.consts.server_chans)
                    .find(|c| prev["app"][c.as_str()] != next["app"][c.as_str()])
                    .cloned()
                    .ok_or("which delivery?")?;
                Some((c.clone(), u(&next["app"][c.as_str()], "off")))
            }
            _ => None,
        };
        if let Some((c, off)) = &delivered {
            expect.push(format!("pub {c} {off}"));
        }

        // Match the core's events.
        let events = std::mem::take(&mut self.out.events);
        let mut got: Vec<String> = Vec::new();
        for e in &events {
            let name = |k: SubKey| {
                self.names
                    .get(&k)
                    .cloned()
                    .unwrap_or_else(|| format!("#{k}"))
            };
            match e {
                Event::Connecting { .. } => got.push("connecting".into()),
                Event::Connected { .. } => got.push("connected".into()),
                Event::Disconnected { .. } => got.push("disconnected".into()),
                Event::Subscribing { sub, .. } => got.push(format!("subscribing {}", name(*sub))),
                Event::Subscribed { sub, info } => {
                    got.push(format!("subscribed {}", name(*sub)));
                    if act == "Sdk_SubscribeReply" {
                        let res = &arr(prev, "toC")[0]["res"];
                        if info.recovered != b(res, "rcv") || info.was_recovering != b(res, "was") {
                            return Err(format!("subscribed {info:?} for result {res}"));
                        }
                    }
                }
                Event::Unsubscribed { sub, .. } => got.push(format!("unsubscribed {}", name(*sub))),
                Event::ServerSubscribed { channel, .. } => {
                    got.push(format!("server_subscribed {channel}"));
                }
                Event::ServerSubscribing { channel } => {
                    got.push(format!("server_subscribing {channel}"));
                }
                Event::ServerUnsubscribed { channel } => {
                    got.push(format!("server_unsubscribed {channel}"));
                }
                Event::Publication { sub, publication } => {
                    if publication.data[..] != payload(publication.offset)[..] {
                        return Err(format!(
                            "publication {} with wrong data",
                            publication.offset
                        ));
                    }
                    got.push(format!("pub {} {}", name(*sub), publication.offset));
                }
                Event::ServerPublication {
                    channel,
                    publication,
                } => {
                    if publication.data[..] != payload(publication.offset)[..] {
                        return Err(format!(
                            "publication {} with wrong data",
                            publication.offset
                        ));
                    }
                    got.push(format!("pub {channel} {}", publication.offset));
                }
                _ => {}
            }
        }
        let (mut a, mut e) = (got.clone(), expect.clone());
        a.sort();
        e.sort();
        if a != e {
            return Err(format!("events: core {got:?}, model {expect:?}"));
        }

        // Commands: the model's new ones are [prev.nid, next.nid).
        let (prev_nid, next_nid) = (i(prev, "nid"), i(next, "nid"));
        let new_cmds: Vec<Value> = arr(next, "toS")
            .iter()
            .filter(|c| i(c, "id") >= prev_nid && i(c, "id") < next_nid)
            .cloned()
            .collect();
        let mut fresh = std::mem::take(&mut self.out.commands);
        for mc in &new_cmds {
            let pos = fresh
                .iter()
                .position(|cc| self.same_command(mc, cc))
                .ok_or_else(|| format!("model command {mc} not sent; core sent {fresh:?}"))?;
            let cc = fresh.remove(pos);
            self.ids.insert(i(mc, "id"), cc.id);
        }
        self.out.commands = fresh;

        // Callbacks.
        let mut cbs = std::mem::take(&mut self.out.callbacks);
        for x in arr(next, "cbs")
            .iter()
            .filter(|x| !arr(prev, "cbs").contains(x))
        {
            let ch = s(x, "ch");
            let pos = cbs
                .iter()
                .position(|cb| match (s(x, "k"), cb) {
                    ("ctoken" | "crefresh", Callback::ConnectionToken { .. }) => true,
                    ("stoken" | "srefresh", Callback::SubscriptionToken { channel, .. }) => {
                        channel == ch
                    }
                    ("state", Callback::GetState { channel, .. }) => channel == ch,
                    _ => false,
                })
                .ok_or_else(|| format!("model callback {x} not started; core started {cbs:?}"))?;
            let flow = match cbs.remove(pos) {
                Callback::ConnectionToken { flow }
                | Callback::SubscriptionToken { flow, .. }
                | Callback::GetState { flow, .. } => flow,
            };
            self.flows.insert(x.to_string(), flow);
        }
        self.out.callbacks = cbs;

        // Timers.
        let waits = nst == "connecting" && s(&next["cl"], "ph") == "wait";
        let armed = self.core.timers.is_armed(TimerKey::Reconnect);
        if waits != armed && !(waits && self.transport_requested()) {
            return Err(format!("reconnect timer: core {armed}, model {waits}"));
        }
        for c in &self.consts.chans {
            let want = b(&next["sub"][c.as_str()], "tmr");
            let got = self
                .core
                .timers
                .is_armed(TimerKey::Resubscribe(self.key(c)));
            if want != got {
                return Err(format!(
                    "resubscribe timer of {c}: core {got}, model {want}"
                ));
            }
        }
        Ok(())
    }

    /// The core skipped the wait (the fallback's first round is immediate).
    fn transport_requested(&self) -> bool {
        self.transport.is_some()
    }

    fn same_command(&self, m: &Value, c: &proto::Command) -> bool {
        let tok = |prefix: &str, t: i64| {
            if t == 0 {
                String::new()
            } else {
                format!("{prefix}{t}")
            }
        };
        let ch = s(m, "ch");
        match s(m, "k") {
            "connect" => c.connect.as_ref().is_some_and(|x| {
                x.token == tok("t", i(m, "tok"))
                    && self.consts.server_chans.iter().all(|sc| {
                        let p = &m["pos"][sc.as_str()];
                        match x.subs.get(sc) {
                            Some(r) => {
                                b(p, "on")
                                    && r.recover
                                    && r.offset == u(p, "off")
                                    && r.epoch == epoch(i(p, "ep"))
                            }
                            None => !b(p, "on"),
                        }
                    })
            }),
            "sub" => c.subscribe.as_ref().is_some_and(|x| {
                x.channel == ch
                    && x.recover == b(m, "rec")
                    && (!x.recover || (x.offset == u(m, "off") && x.epoch == epoch(i(m, "ep"))))
                    && x.token == tok("s", i(m, "tok"))
            }),
            "unsub" => c.unsubscribe.as_ref().is_some_and(|x| x.channel == ch),
            "refresh" => c
                .refresh
                .as_ref()
                .is_some_and(|x| x.token == tok("t", i(m, "tok"))),
            "subrefresh" => c
                .sub_refresh
                .as_ref()
                .is_some_and(|x| x.channel == ch && x.token == tok("s", i(m, "tok"))),
            _ => false,
        }
    }
}

fn replay(trace: &Value) -> R {
    let consts = Consts::from(&trace["constants"]);
    let states = trace["states"].as_array().ok_or("no states")?;
    let init = states[0].as_object().ok_or("bad state")?;
    let mut r = Replay::new(consts, init);
    r.out = Produced::default();
    for st in &states[1..] {
        let diff = st.as_object().ok_or("bad state")?;
        if let Err(e) = r.step(diff) {
            return Err(format!("{e}\n  after: {}", r.log.join(" ")));
        }
    }
    r.no_leftovers()
        .map_err(|e| format!("{e}\n  after: {}", r.log.join(" ")))
}

#[test]
fn tla_traces_replay_into_the_core() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/tla/traces");
    if !dir.exists() {
        return; // not packaged with the published crate
    }
    let mut files: Vec<_> = std::fs::read_dir(&dir)
        .expect("trace directory")
        .filter_map(Result::ok)
        .map(|e| e.path())
        .collect();
    files.retain(|p| p.extension().is_some_and(|e| e == "jsonl"));
    files.sort();
    assert!(!files.is_empty(), "no traces: run `cargo xtask tla-traces`");
    let (mut total, mut failures) = (0, Vec::new());
    for f in files {
        let text = std::fs::read_to_string(&f).expect("trace file");
        for (n, line) in text.lines().enumerate() {
            total += 1;
            let trace: Value = serde_json::from_str(line).expect("trace JSON");
            if let Err(e) = replay(&trace) {
                failures.push(format!(
                    "{} #{n}: {e}",
                    trace["config"].as_str().unwrap_or("?")
                ));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {total} traces diverge:\n{}",
        failures.len(),
        failures
            .iter()
            .take(15)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

/// TLC's counterexamples of the model's bug variants (several of them
/// centrifuge-js today): the core must not follow any of them. Each diverges
/// at the step where the bug shows (printed with `--nocapture`).
#[test]
fn tla_bug_counterexamples_do_not_replay() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/tla/bugs.jsonl");
    let Ok(text) = std::fs::read_to_string(path) else {
        return; // not packaged with the published crate
    };
    let mut n = 0;
    for line in text.lines() {
        let trace: Value = serde_json::from_str(line).expect("trace JSON");
        let cfg = trace["config"].as_str().unwrap_or("?");
        match replay(&trace) {
            Ok(()) => panic!(
                "{cfg}: the core follows the bug's counterexample ({})",
                trace["violated"]
            ),
            Err(e) => println!("{cfg} diverges: {e}"),
        }
        n += 1;
    }
    assert!(n >= 5, "only {n} bug counterexamples");
}
